import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzSliderModule, NzMarks } from 'ng-zorro-antd/slider';
import { HrmControl } from '../shared/hrm-control';

/** hrm-slider — CVA number | [number,number] (range). */
@Component({
  selector: 'hrm-slider',
  imports: [FormsModule, NzSliderModule],
  template: `
    <nz-slider
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      [nzMin]="min()"
      [nzMax]="max()"
      [nzStep]="step()"
      [nzRange]="range()"
      [nzMarks]="marks()"
      [nzDots]="dots()"
      [nzDisabled]="disabled()"></nz-slider>
  `,
  host: { class: 'hrm-slider' },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmSlider), multi: true }],
})
export class HrmSlider extends HrmControl<number | number[]> {
  readonly min = input(0);
  readonly max = input(100);
  readonly step = input(1);
  readonly range = input(false);
  /** Tick marks: map giá trị → nhãn (VD { 0: '0đ', 50: '50%' }). Data do nơi dùng truyền, không hardcode. */
  readonly marks = input<NzMarks | null>(null);
  /** Hiện chấm mốc trên rãnh trượt. */
  readonly dots = input(false);
}
